t='..((((((((.......(.((((((....)))))).(((((((....))))))).).......))))))))..'
seq=['A']*73
pairs={}
stack=[]
for i,c in enumerate(t):
    if c=='(': stack.append(i)
    elif c==')':
        j=stack.pop(); pairs[j]=i; pairs[i]=j
# build stems
seen=set()
stems=[]
for i in sorted(pairs):
    if i in seen: continue
    j=pairs[i]; a,b=i,j; sa=[]; sb=[]
    while a in pairs and pairs[a]==b:
        sa.append(a); sb.append(b); seen.add(a); seen.add(b); a+=1; b-=1
    stems.append((sa,sb))
print('stems:')
for s in stems: print(s[0][0], s[1][0], len(s[0]))
# assign GC to stems alternating
import itertools
gc=[('G','C'),('C','G'),('G','C'),('C','G'),('G','C'),('C','G'),('G','C'),('C','G')]
for s in stems:
    sa,sb=s
    for k in range(len(sa)):
        a=sa[k]; b=sb[k]
        seq[a]=gc[k%len(gc)][0]; seq[b]=gc[k%len(gc)][1]
# loops -> A
for i,c in enumerate(t):
    if c=='.':
        seq[i]='A'
print(''.join(seq))
"

